ui.css:
.hud { font-family: 'Press Start 2P', monospace; color: #fcfcfc; background: #000; padding: 14px 32px 12px; box-shadow: 0 4px 0 #000; image-rendering: pixelated; }
.hud .label { font-size: 16px; color: #f83800; text-transform: uppercase; }
.hud .clock { font-size: 32px; color: #fcfcfc; text-shadow: none; }
.xp { height: 16px; background: #000; box-shadow: 0 0 0 4px #fcfcfc; border-radius: 0; }
.xp-fill { height: 100%; background: repeating-linear-gradient(90deg, #3cbcfc 0 8px, #0058f8 8px 12px, #000 12px 16px); transition: none; }
.window { background: #000; border: 4px solid #fcfcfc; border-radius: 0; box-shadow: 0 0 0 4px #000, inset 0 0 0 4px #000, inset 0 0 0 8px #fcfcfc; }
.dim { background: repeating-conic-gradient(#000 0 25%, transparent 0 50%) 0 0 / 8px 8px; }
@keyframes nesblink { 0% { opacity: 1; } 50% { opacity: 0; } }
.blink { animation: nesblink 1s steps(1) infinite; }
